package es.idynamicsax.ostris.security;
import es.idynamicsax.idax.security.*; import es.idynamicsax.idax.tenant.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.UUID; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class OstrisJwtAuthFilter extends OncePerRequestFilter {
 private final TokenValidator tokens; public OstrisJwtAuthFilter(TokenValidator t,TenantResolver ignored){tokens=t;}
 protected boolean shouldNotFilter(HttpServletRequest r){return r.getRequestURI().startsWith("/actuator/");}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{try{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){var result=tokens.validateAndExtract(h.substring(7));if(result.isValid()){CurrentUser u=result.getCurrentUser();if(u.getTenantId()==null){res.sendError(HttpServletResponse.SC_UNAUTHORIZED);return;}SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,u.getRoles().stream().map(SimpleGrantedAuthority::new).toList()));TenantContext.set(new TenantContext(u.getTenantId(),null,u.getUserId(),u.getUsername(),u.isSuperuser()?TenantContext.DbRole.IDAX_ADMIN:TenantContext.DbRole.IDAX_APP));}}chain.doFilter(req,res);}finally{TenantContext.clear();}}
}
